diff --git a/spec/scripts/port-check.js b/spec/scripts/port-check.js
index aeabab1..6b498e4 100644
--- a/spec/scripts/port-check.js
+++ b/spec/scripts/port-check.js
@@ -47,7 +47,7 @@ function walk(dir, out) {
     if (ent.name === 'node_modules' || ent.name === '.git') continue
     const full = path.join(dir, ent.name)
     if (ent.isDirectory()) walk(full, out)
-    else if (ent.isFile()) out.push(full)
+    else if (ent.isFile() && ent.name.endsWith('.test.js')) out.push(full)
   }
 }
